CREATE TYPE "ProcurementCycleStatus" AS ENUM ('DRAFT','OPEN','INTAKE_CLOSED','PROCESSING','COMPLETED','CANCELLED');
CREATE TYPE "ExecutionStatus" AS ENUM ('DRAFT','READY_FOR_PROCESSING','PROCESSING','SOURCING_READY','COMPLETED','CANCELLED');
CREATE TYPE "ExecutionItemStatus" AS ENUM ('ELIGIBLE','ASSIGNED','IN_PROCESSING','SOURCING_READY','WITHDRAWN','CANCELLED','COMPLETED');
CREATE TYPE "ReadyAllocationEventType" AS ENUM ('GRANTED','REDUCED','WITHDRAWN','CONSUMED','RELEASED','REASSIGNED');
CREATE TYPE "CycleExceptionStatus" AS ENUM ('REQUESTED','APPROVED','REJECTED');
CREATE TYPE "ExecutionChangeStatus" AS ENUM ('REQUESTED','APPROVED','REJECTED','EXECUTED');
CREATE TABLE procurement_cycles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cycle_code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, intake_opens_at TIMESTAMPTZ NOT NULL, intake_closes_at TIMESTAMPTZ NOT NULL, processing_starts_at TIMESTAMPTZ, target_delivery_policy TEXT, status "ProcurementCycleStatus" NOT NULL DEFAULT 'DRAFT', opened_by UUID REFERENCES "User"(id), closed_by UUID REFERENCES "User"(id), closed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_executions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), cycle_id UUID NOT NULL REFERENCES procurement_cycles(id) ON DELETE RESTRICT, status "ExecutionStatus" NOT NULL DEFAULT 'DRAFT', created_by UUID NOT NULL REFERENCES "User"(id), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ, cancelled_at TIMESTAMPTZ, reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_execution_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), execution_id UUID NOT NULL REFERENCES procurement_executions(id) ON DELETE RESTRICT, company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, project_id UUID REFERENCES projects(id) ON DELETE RESTRICT, procurement_need_id UUID NOT NULL REFERENCES procurement_needs(id) ON DELETE RESTRICT, product_identity_id UUID NOT NULL REFERENCES product_identities(id) ON DELETE RESTRICT, allocated_quantity NUMERIC NOT NULL CHECK (allocated_quantity > 0), consumed_quantity NUMERIC NOT NULL DEFAULT 0 CHECK (consumed_quantity >= 0), remaining_quantity NUMERIC NOT NULL CHECK (remaining_quantity >= 0), unit_id UUID NOT NULL REFERENCES unit_definitions(id), need_date DATE NOT NULL, expected_delivery_date DATE, status "ExecutionItemStatus" NOT NULL DEFAULT 'ELIGIBLE', idempotency_key TEXT NOT NULL UNIQUE, created_by UUID NOT NULL REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK (consumed_quantity <= allocated_quantity));
CREATE TABLE ready_allocation_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, procurement_need_id UUID NOT NULL REFERENCES procurement_needs(id) ON DELETE RESTRICT, execution_item_id UUID REFERENCES procurement_execution_items(id) ON DELETE RESTRICT, cycle_id UUID REFERENCES procurement_cycles(id) ON DELETE RESTRICT, event_type "ReadyAllocationEventType" NOT NULL, quantity NUMERIC NOT NULL CHECK (quantity > 0), idempotency_key TEXT UNIQUE, actor_user_id UUID NOT NULL REFERENCES "User"(id), reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE procurement_cycle_exceptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, need_id UUID NOT NULL REFERENCES procurement_needs(id) ON DELETE RESTRICT, original_cycle_id UUID NOT NULL REFERENCES procurement_cycles(id), resulting_cycle_id UUID NOT NULL REFERENCES procurement_cycles(id), reason TEXT NOT NULL, status "CycleExceptionStatus" NOT NULL DEFAULT 'REQUESTED', requested_by UUID NOT NULL REFERENCES "User"(id), decided_by UUID REFERENCES "User"(id), decided_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE execution_change_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES "Company"(id) ON DELETE RESTRICT, execution_item_id UUID NOT NULL REFERENCES procurement_execution_items(id), request_type TEXT NOT NULL, reason TEXT NOT NULL, requested_quantity NUMERIC, status "ExecutionChangeStatus" NOT NULL DEFAULT 'REQUESTED', requested_by UUID NOT NULL REFERENCES "User"(id), decided_by UUID REFERENCES "User"(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX execution_items_company_idx ON procurement_execution_items(company_id);
CREATE INDEX ready_events_need_idx ON ready_allocation_events(procurement_need_id,created_at);
GRANT SELECT, INSERT, UPDATE ON procurement_cycles,procurement_executions,procurement_execution_items,ready_allocation_events,procurement_cycle_exceptions,execution_change_requests TO sco_runtime;
ALTER TABLE procurement_cycles ENABLE ROW LEVEL SECURITY; ALTER TABLE procurement_cycles FORCE ROW LEVEL SECURITY;
ALTER TABLE procurement_executions ENABLE ROW LEVEL SECURITY; ALTER TABLE procurement_executions FORCE ROW LEVEL SECURITY;
CREATE POLICY cycles_internal ON procurement_cycles FOR ALL TO sco_runtime USING (current_setting('app.sco_internal',true)='true') WITH CHECK (current_setting('app.sco_internal',true)='true');
CREATE POLICY executions_internal ON procurement_executions FOR ALL TO sco_runtime USING (current_setting('app.sco_internal',true)='true') WITH CHECK (current_setting('app.sco_internal',true)='true');
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['procurement_execution_items','ready_allocation_events','procurement_cycle_exceptions','execution_change_requests'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY %I_tenant ON %I FOR ALL TO sco_runtime USING (company_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid OR current_setting(''app.sco_internal'',true)=''true'') WITH CHECK (company_id = NULLIF(current_setting(''app.tenant_id'',true),'''')::uuid OR current_setting(''app.sco_internal'',true)=''true'')',t,t); END LOOP; END $$;
